import * as fs from "node:fs/promises";
import * as path from "node:path";
import { pathToFileURL } from "node:url";
const { createConformanceDriver } = await import(pathToFileURL(path.join(process.env.REPO, "scripts/competitive-conformance.ts")).href);
const context = {projectRoot:process.env.REPO, toolsRoot:path.join(process.env.OWNED,"tools"),artifactDir:path.join(process.env.OWNED,"cell"),sourceRoot:path.join(process.env.OWNED,"cell/source"),configPath:path.join(process.env.OWNED,"cell/config.json"),timeoutMs:60000};
const driver=createConformanceDriver("codebase-memory",context);
const requests=[
 {operation:"definitions",subject:{path:"src/leaf.js",symbol:"calibrationLeaf"},limit:50},
 {operation:"direct-callers",subject:{path:"src/leaf.js",symbol:"calibrationLeaf"},limit:50},
 {operation:"direct-callees",subject:{path:"src/entry.js",symbol:"calibrationEntry"},limit:50},
 {operation:"shortest-path",from:{path:"src/entry.js",symbol:"calibrationEntry"},to:{path:"src/leaf.js",symbol:"calibrationLeaf"},limit:50},
 {operation:"definitions",subject:{path:"src/leaf.js",symbol:"calibrationDefinitelyAbsent"},limit:50}
];
try {
 const index=await driver.index();
 const results=[];
 for(const request of requests)results.push({request,response:await driver.request(request)});
 const first=results[0].response;
 const expected=await fs.readFile(path.join(context.sourceRoot,"src/leaf.js"),"utf8");
 if(first.status!=="success"||first.normalized.definitions?.length!==1||first.normalized.definitions[0].path!=="src/leaf.js"||first.normalized.definitions[0].symbol!=="calibrationLeaf"||first.normalized.definitions[0].content!==expected)throw new Error("Real CBM returned incorrect leaf identity/body");
 if(results[4].response.status!=="success"||results[4].response.normalized.definitions?.length!==0)throw new Error("Absent definition did not remain absent");
 console.log(JSON.stringify({index,results},null,2));
}finally{await driver.close();}

